window.docContents[184].resolve({"/Lists/#Logical-Foundations--Lists___-Working-with-Structured-Data--Lists-of-Numbers--Length":{"contents":"\n\n\n\ndef length (l : NatList) : Nat :=\n  match l with\n  | [] => 0\n  | _ :: t => (length t) + 1\n\n\nSome simple facts about list lengths:\n\ntheorem length_nil : [].length = 0 := by rfl\n\ntheorem length_cons (n : Nat) (l : NatList) :\n  (n :: l).length = l.length + 1 := by rfl\n\n\n","context":"Logical Foundations\u0009Lists: Working with Structured Data\u0009Lists of Numbers","header":"5.2.2. Length","id":"/Lists/#Logical-Foundations--Lists___-Working-with-Structured-Data--Lists-of-Numbers--Length"}});